+  systemd.user.services.herdr.Service = {
+    Type = "simple";
+    Environment =
+      "PATH=/home/faviann/.local/bin:/home/faviann/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
+    ExecStart = "/home/faviann/.local/bin/herdr server";
